#include "src/lexer/lexer.hpp"
#include <cstdio>
#include <fstream>
#include <iostream>
#include <sstream>
#include <stdexcept>
#include <string>
#include <vector>

// C++ compiles with name mangling; extern "C" tells the linker to match
// the unmangled C symbols generated by Flex in lex.yy.c.
extern "C" {
    int yylex(void);
    void yyrestart(FILE* input_file);
    extern FILE* yyin;
    extern FILE* yyout;
    extern int flex_error_count;
}

namespace {

std::vector<std::string> run_flex_on_string(const std::string& source, int& out_errors) {
    FILE* in_mem = std::tmpfile();
    FILE* out_mem = std::tmpfile();
    if (!in_mem || !out_mem) {
        throw std::runtime_error("Failed to create temporary files for Flex");
    }

    std::fwrite(source.data(), 1, source.size(), in_mem);
    std::rewind(in_mem);

    flex_error_count = 0;
    yyin = in_mem;
    yyout = out_mem;
    yyrestart(yyin); // Reset Flex's internal buffer state before scanning
    yylex();

    out_errors = flex_error_count;
    std::fclose(in_mem);

    std::rewind(out_mem);
    std::vector<std::string> tokens;
    char line[256];
    while (std::fgets(line, sizeof(line), out_mem)) {
        std::string tok(line);
        while (!tok.empty() && (tok.back() == '\n' || tok.back() == '\r')) {
            tok.pop_back();
        }
        if (!tok.empty()) {
            tokens.push_back(tok);
        }
    }
    std::fclose(out_mem);
    return tokens;
}

std::string read_entire_file(const std::string& path) {
    std::ifstream file(path);
    if (!file) throw std::runtime_error("Cannot open file: " + path);
    std::ostringstream ss;
    ss << file.rdbuf();
    return ss.str();
}

} // namespace

int main() {
    try {
        std::ifstream rules_file("src/lexer/test_files/phase1.rules");
        if (!rules_file) throw std::runtime_error("Cannot open phase1.rules");
        LexerDefinition language(rules_file);

        // Test 1: Full parity on phase1_program.java
        const std::string program = read_entire_file("src/lexer/test_files/phase1_program.java");

        std::istringstream cpp_stream(program);
        Scanner scanner = language.scanner(cpp_stream);
        std::vector<std::string> cpp_tokens;
        while (auto token = scanner.nextToken()) {
            cpp_tokens.push_back(token->type);
        }

        int flex_errors = 0;
        std::vector<std::string> flex_tokens = run_flex_on_string(program, flex_errors);

        if (!scanner.errorOffsets().empty() || flex_errors != 0) {
            throw std::runtime_error("Unexpected lexical errors on valid sample program");
        }
        if (cpp_tokens != flex_tokens) {
            throw std::runtime_error("Token mismatch between C++ Scanner (" +
                                     std::to_string(cpp_tokens.size()) + ") and Flex (" +
                                     std::to_string(flex_tokens.size()) + ")");
        }
        std::cout << "PASS [1/2]: C++ Scanner and Flex produced identical "
                  << cpp_tokens.size() << " tokens on phase1_program.java\n";

        // Test 2: Error recovery & maximal munch parity on malformed input
        const std::string dirty_input = "int x = 10 @ ? while == = 3.14E2;";
        std::istringstream dirty_stream(dirty_input);
        Scanner dirty_scanner = language.scanner(dirty_stream);
        std::vector<std::string> dirty_cpp_tokens;
        while (auto token = dirty_scanner.nextToken()) {
            dirty_cpp_tokens.push_back(token->type);
        }

        int dirty_flex_errors = 0;
        std::vector<std::string> dirty_flex_tokens = run_flex_on_string(dirty_input, dirty_flex_errors);

        if (dirty_cpp_tokens != dirty_flex_tokens) {
            throw std::runtime_error("Token mismatch during error recovery test");
        }
        if (static_cast<int>(dirty_scanner.errorOffsets().size()) != dirty_flex_errors) {
            throw std::runtime_error("Error count mismatch: C++=" +
                                     std::to_string(dirty_scanner.errorOffsets().size()) +
                                     ", Flex=" + std::to_string(dirty_flex_errors));
        }
        std::cout << "PASS [2/2]: Error recovery parity verified ("
                  << dirty_flex_errors << " invalid bytes skipped, "
                  << dirty_cpp_tokens.size() << " tokens matched)\n";

        return 0;
    } catch (const std::exception& ex) {
        std::cerr << "FAIL: " << ex.what() << '\n';
        return 1;
    }
}